    inline std::unordered_map<uint32_t, int64_t> BuildAchievementIdToLocationId()
    {
        std::unordered_map<uint32_t, int64_t> result;
        for (auto const& row : ACHIEVEMENT_ID_TO_LOCATION_ID_RAW)
            result.emplace(row.first, row.second);
        return result;
    }
