    inline std::unordered_map<int64_t, uint32_t> BuildApItemIdToAchievementId()
    {
        std::unordered_map<int64_t, uint32_t> result;
        for (auto const& row : AP_ITEM_ID_TO_ACHIEVEMENT_ID_RAW)
            result.emplace(row.first, row.second);
        return result;
    }
